-- =============================================================================
-- 521 — LE CAHIER D'EXERCICES DE 1RE (partie 9)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 521 --niveau 1re --fichiers enseignement-scientifique.n2,espagnol.jumelles-2 --suffixe 9 > supabase/contenu/521_exercices_1re_9.sql
--
-- 60 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   enseignement-scientifique.n2  33 exercices · 11 chapitres
--   espagnol.jumelles-2     27 exercices · 9 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('ab932ad3-ab0c-5db8-b1d3-0ba55bd95c18'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les mesures de Léo sur son monocorde","competence":"lire-tableau","situation":"En cours de sciences, Léo fait vibrer une corde tendue de 60 cm : elle émet un la à 220 Hz. Il glisse ensuite un chevalet sous la corde pour raccourcir la partie qui vibre, et il note ses mesures.","documents":[{"id":"mono","type":"tableau","titre":"Les mesures de Léo","colonnes":["Position du chevalet","Longueur qui vibre (cm)","Fréquence (Hz)"],"lignes":[["Corde entière",60,220],["Chevalet au milieu",30,"?"],["Chevalet aux deux tiers",40,330]],"enteteLignes":true,"source":"Mesures écrites pour l’exercice"}],"questions":[{"enonce":"Touche la plus petite longueur de corde qui vibre.","aide":"Compare les trois longueurs de la colonne centrale.","type":"zone","document":"mono","multiple":false},{"enonce":"La longueur est divisée par 2 : quelle est la fréquence du son, en Hz ?","aide":"La fréquence est inversement proportionnelle à la longueur qui vibre.","type":"nombre","unite":"Hz"},{"enonce":"Quel est le rapport de fréquences entre le son à 330 Hz et le son à 220 Hz ?","aide":"Divise la fréquence la plus haute par la plus basse.","type":"nombre"},{"enonce":"Quel intervalle musical correspond à ce rapport de 3/2 ?","aide":"Rappelle-toi le tableau des intervalles consonants du cours.","type":"choix","options":[{"id":"a","texte":"Une quinte"},{"id":"b","texte":"Une octave"},{"id":"c","texte":"Un demi-ton"},{"id":"d","texte":"Une quarte"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La plus petite longueur est **30 cm**, quand le chevalet est placé au milieu de la corde."},{"cle":{"type":"nombre","valeur":440,"tolerance":0},"affichage":"440 Hz","explication":"Diviser la longueur par 2 **double** la fréquence : 2 × 220 = **440 Hz**. C’est la note une octave plus haut."},{"cle":{"type":"nombre","valeur":1.5,"tolerance":0},"affichage":"1,5","explication":"330 ÷ 220 = **1,5**, c’est-à-dire 3/2."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le rapport 3/2 est celui de la **quinte**, l’octave valant 2/1 et la quarte 4/3."}]$ex$::jsonb),
  ('ab932ad3-ab0c-5db8-b1d3-0ba55bd95c18'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Zélie empile des quintes","competence":"calculer","situation":"Zélie veut reconstruire la gamme de Pythagore à partir d’un do dont le rapport de fréquences est 1. Elle empile des quintes (× 3/2) et, quand le résultat dépasse 2, elle le ramène dans l’octave en divisant par 2 autant de fois qu’il le faut.","documents":[{"id":"quintes","type":"tableau","titre":"Le carnet de Zélie","colonnes":["Quinte empilée","Note","Rapport obtenu","Rapport ramené dans l’octave"],"lignes":[["1re quinte","sol","1,5","1,5"],["2e quinte","ré","2,25","?"],["3e quinte","la","3,375","?"],["4e quinte","mi","5,0625","?"]],"enteteLignes":true,"source":"Calculs de Zélie, valeurs exactes"}],"questions":[{"enonce":"Touche le premier rapport obtenu qui dépasse 2 : il faudra le ramener dans l’octave.","aide":"Regarde la colonne « Rapport obtenu » de haut en bas.","type":"zone","document":"quintes","multiple":false},{"enonce":"Quel est le rapport du ré une fois ramené dans l’octave ?","aide":"Divise 2,25 par 2.","type":"nombre"},{"enonce":"Quel est le rapport du la une fois ramené dans l’octave ?","aide":"3,375 est compris entre 2 et 4 : une seule division par 2 suffit.","type":"nombre"},{"enonce":"Quel est le rapport du mi une fois ramené dans l’octave ?","aide":"5,0625 est compris entre 4 et 8 : il faut diviser par 2 deux fois, donc par 4.","type":"nombre"},{"enonce":"Range ces quatre notes de la plus grave à la plus aiguë, d’après leurs rapports ramenés dans l’octave.","aide":"Plus le rapport de fréquences est grand, plus la note est aiguë.","type":"ordre","items":[{"id":"a","texte":"ré"},{"id":"b","texte":"sol"},{"id":"c","texte":"la"},{"id":"d","texte":"mi"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Le premier rapport supérieur à 2 est **2,25** (la note ré) : au-delà de 2, on a changé d’octave."},{"cle":{"type":"nombre","valeur":1.125,"tolerance":0},"affichage":"1,125","explication":"2,25 ÷ 2 = **1,125**."},{"cle":{"type":"nombre","valeur":1.6875,"tolerance":0},"affichage":"1,6875","explication":"3,375 ÷ 2 = **1,6875**."},{"cle":{"type":"nombre","valeur":1.2656,"tolerance":0.001},"affichage":"1,2656","explication":"5,0625 ÷ 4 = 1,265625, soit environ **1,266**."},{"cle":{"type":"ordre","ids":["a","d","b","c"]},"explication":"Les rapports valent 1,125 (ré) < 1,266 (mi) < 1,5 (sol) < 1,6875 (la) : **ré, mi, sol, la**."}]$ex$::jsonb),
  ('ab932ad3-ab0c-5db8-b1d3-0ba55bd95c18'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Pourquoi le piano ne suit plus Pythagore","competence":"raisonner","situation":"Mathilde accorde un piano. Si elle accorde par quintes pures (rapport 3/2) douze fois de suite, elle devrait retomber sur sa note de départ sept octaves plus haut. Elle compare cette gamme à la gamme tempérée, où l’octave est coupée en douze demi-tons égaux.","documents":[{"id":"pyth","type":"tableau","titre":"Deux empilements pour la même note","colonnes":["Empilement","Calcul","Valeur"],"lignes":[["Sept octaves","2⁷","128"],["Douze quintes","(3/2)¹²","129,746"]],"enteteLignes":true,"source":"Valeurs arrondies au millième"},{"id":"temp","type":"tableau","titre":"Rapports de la gamme tempérée","colonnes":["Nombre de demi-tons","Rapport de fréquences"],"lignes":[[5,"1,335"],[6,"1,414"],[7,"1,498"],[8,"1,587"]],"enteteLignes":true,"source":"Valeurs de 2^(n/12), arrondies au millième"}],"questions":[{"enonce":"Calcule le rapport (3/2)¹² ÷ 2⁷ entre les deux valeurs du premier document, arrondi au millième.","aide":"Divise 129,746 par 128.","type":"nombre"},{"enonce":"Pourquoi un piano accordé uniquement par quintes pures sonne-t-il faux dans certaines tonalités ?","aide":"Pense à l’écart entre 129,746 et 128.","type":"choix","options":[{"id":"a","texte":"Les cordes se détendent un peu plus à chaque nouvelle quinte accordée"},{"id":"b","texte":"Les quintes pures ne sont pas des intervalles consonants pour l’oreille humaine"},{"id":"c","texte":"Les fréquences de la gamme sont toutes des nombres décimaux non entiers"},{"id":"d","texte":"La gamme ne se referme pas : douze quintes dépassent sept octaves"}],"multiple":false},{"enonce":"Touche le rapport tempéré qui s’approche le plus de la quinte pure, de rapport 3/2.","aide":"Cherche la valeur la plus proche de 1,5.","type":"zone","document":"temp","multiple":false},{"enonce":"La quinte tempérée (1,498) est plus basse que la quinte pure (1,5). De quel pourcentage, arrondi au dixième ?","aide":"Calcule (1,5 − 1,498) ÷ 1,5, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Relie chaque notion à ce qui la décrit.","aide":"Chaque gamme a un avantage et un défaut : retrouve-les dans les deux tableaux.","type":"association","gauche":[{"id":"g0","texte":"Gamme de Pythagore"},{"id":"g1","texte":"Comma pythagoricien"},{"id":"g2","texte":"Gamme tempérée"}],"droite":[{"id":"d0","texte":"Écart d’environ 1,4 % entre douze quintes et sept octaves"},{"id":"d1","texte":"Douze demi-tons égaux, aucun intervalle parfaitement juste"},{"id":"d2","texte":"Quintes pures, mais une gamme qui ne se referme pas"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":1.014,"tolerance":0.0006},"affichage":"1,014","explication":"129,746 ÷ 128 ≈ **1,014** : douze quintes dépassent sept octaves d’environ 1,4 %. C’est le comma pythagoricien."},{"cle":{"type":"choix","ids":["d"]},"explication":"Aucune puissance de 3/2 n’est égale à une puissance de 2 : la gamme de Pythagore **ne se referme pas**, d’où le comma."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Le rapport **1,498** (7 demi-tons) est le plus proche de 1,5 : c’est la quinte tempérée."},{"cle":{"type":"nombre","valeur":0.1,"tolerance":0.05},"affichage":"0,1 %","explication":"(1,5 − 1,498) ÷ 1,5 ≈ 0,0013, soit environ **0,1 %** : l’écart est minuscule, on ne l’entend presque pas."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"La gamme de Pythagore est pure mais ne se ferme pas (comma ≈ 1,4 %) ; la gamme tempérée sacrifie la pureté pour jouer **dans toutes les tonalités**."}]$ex$::jsonb),
  ('9b2242cc-36d2-5b1d-badb-346e62bdbbe1'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un signal échantillonné toutes les 0,5 ms","competence":"lire-graphique","situation":"Sacha numérise un son très simple. Un appareil mesure la tension du signal à intervalles réguliers : chaque point du graphique est un échantillon, déjà arrondi à une valeur entière.","documents":[{"id":"sig","type":"graphique","forme":"courbe","titre":"Les échantillons de Sacha","categories":["0","0,5","1","1,5","2","2,5","3","3,5","4"],"series":[{"nom":"Tension","valeurs":[0,3,5,3,0,-3,-5,-3,0],"teinte":"violet"}],"axeY":{"titre":"Tension","unite":"en V","min":-6,"max":6,"pas":2},"axeX":{"titre":"Temps (ms)"},"valeurs":false,"source":"Signal écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’instant où la tension est la plus élevée.","aide":"Cherche le point le plus haut de la courbe.","type":"zone","document":"sig","multiple":false},{"enonce":"Deux échantillons successifs sont séparés de 0,5 ms. Quelle est la fréquence d’échantillonnage, en Hz ?","aide":"La fréquence est l’inverse de la durée : 0,5 ms = 0,0005 s.","type":"nombre","unite":"Hz"},{"enonce":"Le signal revient à la même valeur, dans le même sens, au bout de 4 ms. Quelle est sa fréquence, en Hz ?","aide":"La période vaut 4 ms = 0,004 s ; la fréquence est son inverse.","type":"nombre","unite":"Hz"},{"enonce":"Cet échantillonnage respecte-t-il le critère de Shannon-Nyquist pour ce signal ?","aide":"Le critère impose fe ≥ 2 × fmax.","type":"choix","options":[{"id":"a","texte":"Non : il faudrait au moins 44 100 Hz pour tout son"},{"id":"b","texte":"Non : fe devrait être exactement égale à 250 Hz"},{"id":"c","texte":"Oui : 2 000 Hz dépasse largement 2 × 250 Hz = 500 Hz"},{"id":"d","texte":"Oui, mais seulement parce que la tension devient négative"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"La tension maximale, **5 V**, est mesurée à l’instant **1 ms**."},{"cle":{"type":"nombre","valeur":2000,"tolerance":0},"affichage":"2000 Hz","explication":"fe = 1 ÷ 0,0005 s = **2 000 Hz** : 2 000 mesures par seconde."},{"cle":{"type":"nombre","valeur":250,"tolerance":0},"affichage":"250 Hz","explication":"f = 1 ÷ 0,004 s = **250 Hz**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Il faut fe ≥ 2 × 250 = 500 Hz ; comme fe = 2 000 Hz, le critère est **largement respecté**."}]$ex$::jsonb),
  ('9b2242cc-36d2-5b1d-badb-346e62bdbbe1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois façons de numériser un son","competence":"calculer","situation":"Inès compare trois formats de numérisation du son : la téléphonie, le CD audio et l’enregistrement en studio. Elle veut comprendre ce que chacun capte, et ce qu’il coûte en données.","documents":[{"id":"formats","type":"tableau","titre":"Trois formats numériques","colonnes":["Format","Échantillonnage (Hz)","Résolution (bits)","Voies"],"lignes":[["Téléphone","8 000",8,1],["CD audio","44 100",16,2],["Studio","96 000",24,2]],"enteteLignes":true,"source":"Caractéristiques usuelles, arrondies"}],"questions":[{"enonce":"Touche la résolution qui permet de distinguer le plus de niveaux d’amplitude.","aide":"Avec n bits, on dispose de 2ⁿ niveaux : plus n est grand, plus il y a de niveaux.","type":"zone","document":"formats","multiple":false},{"enonce":"Quelle fréquence maximale un son peut-il avoir pour être numérisé correctement en téléphonie, en Hz ?","aide":"Shannon-Nyquist : fe ≥ 2 × fmax, donc fmax ≤ fe ÷ 2.","type":"nombre","unite":"Hz"},{"enonce":"Quel est le débit du CD audio, en kbit/s (arrondi à l’unité) ?","aide":"Débit = fe × nombre de bits × nombre de voies, en bits par seconde.","type":"nombre","unite":"kbit/s"},{"enonce":"Quelle est la taille d’un morceau de 3 minutes au format CD, en Mo (arrondie à l’unité ; 1 Mo = 1 000 000 octets) ?","aide":"Multiplie le débit par 180 s, puis divise par 8 pour passer des bits aux octets.","type":"nombre","unite":"Mo"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Avec **24 bits**, le format studio dispose de 2²⁴ niveaux : c’est la résolution la plus fine du tableau."},{"cle":{"type":"nombre","valeur":4000,"tolerance":0},"affichage":"4000 Hz","explication":"fmax = 8 000 ÷ 2 = **4 000 Hz** : au-delà, le signal serait mal restitué."},{"cle":{"type":"nombre","valeur":1411,"tolerance":1},"affichage":"1411 kbit/s","explication":"44 100 × 16 × 2 = 1 411 200 bit/s, soit environ **1 411 kbit/s**."},{"cle":{"type":"nombre","valeur":32,"tolerance":0.5},"affichage":"32 Mo","explication":"1 411 200 × 180 ÷ 8 = 31 752 000 octets, soit environ **32 Mo**."}]$ex$::jsonb),
  ('9b2242cc-36d2-5b1d-badb-346e62bdbbe1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Huit gigaoctets pour la playlist de Nour","competence":"raisonner","situation":"Nour veut remplir son téléphone de musique avant un long voyage. Elle hésite entre garder les fichiers du CD et les compresser en MP3.","documents":[{"id":"debits","type":"tableau","titre":"Les formats comparés","colonnes":["Format","Compression","Débit (kbit/s)"],"lignes":[["WAV (comme le CD)","aucune",1411],["FLAC","sans perte","environ 700"],["MP3 haute qualité","avec perte",320],["MP3 standard","avec perte",128]],"enteteLignes":true,"source":"Ordres de grandeur arrondis ; le débit d’un FLAC varie selon le morceau"},{"id":"tel","type":"texte","genre":"consigne","titre":"Le téléphone de Nour","blocs":["Mémoire libre : 8 Go, soit 8 000 Mo.","Tous ses morceaux durent 3 minutes (180 s).","On prend 1 Mo = 1 000 000 octets, et 1 octet = 8 bits."]}],"questions":[{"enonce":"Touche le format qui produit les fichiers les plus légers.","aide":"Un débit plus faible donne un fichier plus petit.","type":"zone","document":"debits","multiple":false},{"enonce":"Quelle est la taille d’un morceau de 3 minutes en MP3 standard, en Mo (arrondie au dixième) ?","aide":"128 000 bit/s × 180 s ÷ 8 donne des octets.","type":"nombre","unite":"Mo"},{"enonce":"Par quel facteur le MP3 standard réduit-il le débit du format WAV (arrondi à l’unité) ?","aide":"Divise 1 411 par 128.","type":"nombre"},{"enonce":"Combien de morceaux entiers de 2,88 Mo tiennent dans 8 000 Mo ?","aide":"Divise 8 000 par 2,88 et garde la partie entière.","type":"nombre"},{"enonce":"Classe ces éléments selon le type de compression auquel ils se rapportent.","aide":"Une compression avec perte supprime ce que l’oreille perçoit mal ; l’information n’est alors plus récupérable.","type":"categories","categories":[{"id":"c0","texte":"Compression sans perte"},{"id":"c1","texte":"Compression avec perte"}],"items":[{"id":"i0","texte":"MP3"},{"id":"i1","texte":"ZIP"},{"id":"i2","texte":"AAC"},{"id":"i3","texte":"Restitue le fichier d’origine à l’identique"},{"id":"i4","texte":"Supprime les sons masqués"},{"id":"i5","texte":"FLAC"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c2"]},"explication":"Le **MP3 standard** (128 kbit/s) a le débit le plus faible : ses fichiers sont les plus légers."},{"cle":{"type":"nombre","valeur":2.9,"tolerance":0.06},"affichage":"2,9 Mo","explication":"128 000 × 180 ÷ 8 = 2 880 000 octets, soit environ **2,9 Mo**."},{"cle":{"type":"nombre","valeur":11,"tolerance":0},"affichage":"11","explication":"1 411 ÷ 128 ≈ **11** : c’est l’ordre de grandeur « divisé par dix » du cours."},{"cle":{"type":"nombre","valeur":2777,"tolerance":0},"affichage":"2777","explication":"8 000 ÷ 2,88 ≈ 2 777,8 : **2 777** morceaux entiers au maximum."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"FLAC et ZIP sont **sans perte** ; MP3 et AAC sont **avec perte** : ils suppriment sons masqués et fréquences extrêmes."}]$ex$::jsonb),
  ('8a7ccdc0-57a3-5a37-93fa-29dd7d0d93f7'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le trajet d’un son dans l’oreille","competence":"observer-schema","situation":"Adel suit en classe le trajet d’un son : de l’air extérieur jusqu’au cerveau, il traverse plusieurs organes. Sa fiche contient un trou : un organe manque.","documents":[{"id":"trajet","type":"chaine","titre":"Du pavillon au cortex","disposition":"colonne","noeuds":[{"id":"z1","texte":"Pavillon","emoji":"👂"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Tympan"},{"id":"z4","texte":"Osselets"},{"id":"z5","texte":"Cochlée"},{"id":"z6","texte":"Nerf auditif"},{"id":"z7","texte":"Aires auditives du cortex"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"},{"de":"z5","a":"z6"},{"de":"z6","a":"z7"}]}],"questions":[{"enonce":"Quel organe manque à la place du « ? » entre le pavillon et le tympan ?","aide":"Le pavillon capte le son et le canalise vers le tympan.","type":"choix","options":[{"id":"a","texte":"La trompe d’Eustache"},{"id":"b","texte":"Le conduit auditif"},{"id":"c","texte":"Le nerf optique"},{"id":"d","texte":"La membrane basilaire"}],"multiple":false},{"enonce":"Touche l’élément qui vibre sous l’effet des variations de pression de l’air.","aide":"C’est la membrane qui ferme le conduit auditif.","type":"zone","document":"trajet","multiple":false},{"enonce":"Relie chaque élément à l’étage de l’oreille où il se trouve.","aide":"Les étages vont de l’extérieur vers l’intérieur : externe, moyenne, interne.","type":"association","gauche":[{"id":"g0","texte":"Pavillon"},{"id":"g1","texte":"Osselets"},{"id":"g2","texte":"Cochlée"}],"droite":[{"id":"d0","texte":"Oreille interne"},{"id":"d1","texte":"Oreille externe"},{"id":"d2","texte":"Oreille moyenne"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"Le son passe par le **conduit auditif**, qui le canalise jusqu’au tympan."},{"cle":{"type":"zone","ids":["z3"]},"explication":"Le **tympan** vibre quand la pression de l’air varie ; il transmet cette vibration aux osselets."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Le pavillon appartient à l’oreille **externe**, les osselets à l’oreille **moyenne**, la cochlée à l’oreille **interne**."}]$ex$::jsonb),
  ('8a7ccdc0-57a3-5a37-93fa-29dd7d0d93f7'::uuid, 2, 2, 10, 35, 4,
