  ('9f05bc3b-6398-5c01-82ef-436b6e82bc94'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le chômage à Valmont : points ou pourcentages ?","competence":"lire-graphique","situation":"Dans la ville imaginaire de Valmont, le journal local écrit « le chômage augmente de 2 % en 2020 ». Une lectrice proteste : la phrase est ambiguë. Le graphique donne les taux de chômage de trois années.","documents":[{"id":"chomage","type":"graphique","forme":"barres","titre":"Taux de chômage à Valmont","categories":["2019","2020","2021"],"series":[{"nom":"Taux de chômage","valeurs":[8,10,9],"teinte":"turquoise"}],"axeY":{"titre":"Taux de chômage","unite":"en %","min":0,"max":12,"pas":2},"axeX":{"titre":"Année"},"valeurs":true,"source":"Chiffres imaginés pour l’exercice"}],"questions":[{"enonce":"Touche l’année où le taux de chômage est le plus élevé.","aide":"Cherche la barre la plus haute.","type":"zone","document":"chomage","multiple":false},{"enonce":"De combien de points de pourcentage le taux augmente-t-il entre 2019 et 2020 ?","aide":"Une variation en points est une simple différence entre les deux taux.","type":"nombre","unite":"points"},{"enonce":"Quel est le taux d’évolution du chômage entre 2019 et 2020, en % ?","aide":"Taux d’évolution = (valeur finale − valeur initiale) ÷ valeur initiale.","type":"nombre","unite":"%"},{"enonce":"Entre 2020 et 2021, le taux passe de 10 % à 9 %. Quelle phrase est exacte ?","aide":"Distingue la différence absolue (en points) et le taux d’évolution (relatif).","type":"choix","options":[{"id":"a","texte":"Il baisse de 10 points de pourcentage, soit de 1 % en valeur relative"},{"id":"b","texte":"Il baisse de 11 %, car 9 est inférieur de 11 à 20"},{"id":"c","texte":"Il baisse de 1 point de pourcentage, soit de 10 % en valeur relative"},{"id":"d","texte":"Il baisse de 1 %, ce qui revient à 1 point de pourcentage"}],"multiple":false},{"enonce":"En prenant 2019 comme année de référence (indice 100), quel est l’indice du taux de 2021 ?","aide":"Indice = 100 × valeur ÷ valeur de référence.","type":"nombre"}]}$ex$::jsonb,
