  ('9f05bc3b-6398-5c01-82ef-436b6e82bc94'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Hausse puis baisse de 20 % : le même prix ?","competence":"argumenter","situation":"Un abonnement de streaming augmente de 20 % en 2023, puis baisse de 20 % en 2024. Hugo affirme que le prix est revenu à son niveau de départ. Inès n’en est pas convaincue : à vous de trancher.","documents":[{"id":"prix","type":"tableau","titre":"Le prix mensuel de l’abonnement","colonnes":["Année","Prix (€)","Évolution"],"lignes":[["2022",10,"—"],["2023",12,"+ 20 %"],["2024","?","− 20 %"]],"enteteLignes":true,"source":"Tarifs imaginés pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Hugo","emoji":"👦","cote":"gauche"},{"nom":"Inès","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Hugo","texte":"+ 20 % puis − 20 %, ça se compense : on est revenus à 10 € !"},{"qui":"Inès","texte":"Je n’en suis pas sûre… on calcule ?"}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Quel est le prix de l’abonnement en 2024, en euros ?","aide":"Une baisse de 20 % correspond au coefficient 0,80, appliqué au prix de 2023.","type":"nombre","unite":"€"},{"enonce":"Quel est le coefficient multiplicateur global de 2022 à 2024 ?","aide":"Les coefficients successifs se multiplient : 1,20 × 0,80.","type":"nombre"},{"enonce":"De quel pourcentage le prix a-t-il baissé entre 2022 et 2024 ?","aide":"Un coefficient de 0,96 correspond à 1 − 0,04.","type":"nombre","unite":"%"},{"enonce":"Où Hugo se trompe-t-il ?","aide":"Sur quel prix chaque pourcentage est-il calculé ?","type":"choix","options":[{"id":"a","texte":"Il aurait dû additionner 20 % et 20 % pour obtenir 40 % au total"},{"id":"b","texte":"Une hausse de 20 % ne peut jamais être annulée par une baisse"},{"id":"c","texte":"Les deux 20 % ne portent pas sur la même valeur de départ"},{"id":"d","texte":"Le prix de 2022 était déjà trop élevé pour pouvoir encore baisser"}],"multiple":false},{"enonce":"Après la hausse de 20 %, de quel pourcentage faut-il baisser le prix pour retrouver exactement 10 € (arrondi au dixième) ?","aide":"Il faut multiplier par l’inverse de 1,20.","type":"nombre","unite":"%"}]}$ex$::jsonb,
