  ('962c9d8e-f34f-5461-92f1-fe18cf6ce2a0'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Pile ou face, de plus en plus de lancers","competence":"experimenter","situation":"Au tableur, Karim simule des lancers d’une pièce équilibrée. Après chaque tranche de 100 lancers, il note la fréquence de « pile » depuis le début de l’expérience.","documents":[{"id":"simu","type":"graphique","forme":"courbe","titre":"Fréquence de « pile » selon le nombre de lancers","categories":["100","200","300","400","500","600"],"series":[{"nom":"Fréquence de « pile »","valeurs":[0.57,0.53,0.52,0.515,0.508,0.505],"teinte":"violet"}],"axeY":{"titre":"Fréquence","min":0.5,"max":0.58,"pas":0.02},"axeX":{"titre":"Nombre de lancers"},"valeurs":true,"source":"Simulation écrite pour l’exercice, valeurs arrondies"}],"questions":[{"enonce":"Touche le nombre de lancers pour lequel la fréquence est la plus éloignée de 0,5.","aide":"Cherche le point le plus haut de la courbe.","type":"zone","document":"simu","multiple":false},{"enonce":"Combien de « pile » Karim a-t-il obtenus au bout de 300 lancers ?","aide":"Multiplie la fréquence lue par le nombre de lancers.","type":"nombre"},{"enonce":"Pour 400 lancers et p = 0,5, quelle est la borne supérieure de l’intervalle de fluctuation [p − 1/√n ; p + 1/√n] ?","aide":"Calcule d’abord 1/√400 : √400 = 20.","type":"nombre"},{"enonce":"Pour 100 lancers, l’intervalle de fluctuation est [0,4 ; 0,6]. Que dire de la fréquence 0,57 obtenue ?","aide":"Compare 0,57 aux bornes 0,4 et 0,6.","type":"choix","options":[{"id":"a","texte":"Elle est hors de l’intervalle, donc on peut affirmer que la pièce est truquée"},{"id":"b","texte":"Elle est dans l’intervalle : l’écart est normal pour une pièce équilibrée"},{"id":"c","texte":"Elle devrait être égale à 0,5 si la pièce est vraiment équilibrée"},{"id":"d","texte":"Elle prouve que la probabilité d’obtenir pile vaut en réalité 0,57"}],"multiple":false},{"enonce":"Que montre la courbe quand le nombre de lancers augmente ?","aide":"Observe l’écart entre la courbe et 0,5 de gauche à droite.","type":"choix","options":[{"id":"a","texte":"La fréquence s’éloigne de 0,5 de plus en plus"},{"id":"b","texte":"La fréquence ne dépend plus du nombre de lancers"},{"id":"c","texte":"La fréquence se rapproche de 0,5 et fluctue de moins en moins"},{"id":"d","texte":"La fréquence finit par valoir exactement 0,5 à chaque tranche"}],"multiple":false}]}$ex$::jsonb,
