  ('962c9d8e-f34f-5461-92f1-fe18cf6ce2a0'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un sondage sur le menu du jeudi","competence":"argumenter","situation":"Le directeur d’un lycée affirme que la moitié des élèves souhaitent un menu végétarien le jeudi. Un délégué vérifie avec un sondage. À vous de dire si l’affirmation tient.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Le sondage du délégué","blocs":["Le directeur d’un lycée de 1 500 élèves affirme que « la moitié des élèves souhaitent un menu végétarien chaque jeudi ».","Un délégué interroge 400 élèves tirés au sort : 188 répondent qu’ils souhaitent ce menu."],"source":"Texte écrit pour l’exercice"},{"id":"racine","type":"tableau","titre":"Taille de l’échantillon et fluctuation","colonnes":["Taille n de l’échantillon","1/√n"],"lignes":[[100,"0,1"],[900,"0,033"],[2500,"0,02"],[10000,"0,01"]],"enteteLignes":true,"source":"Valeurs arrondies au millième"}],"questions":[{"enonce":"Quelle est la fréquence observée d’élèves favorables dans l’échantillon ?","aide":"Divise le nombre de réponses favorables par la taille de l’échantillon.","type":"nombre"},{"enonce":"Si p = 0,5 et n = 400, quelle est la borne inférieure de l’intervalle de fluctuation à 95 % ?","aide":"Calcule 1/√400, puis soustrais-le à 0,5.","type":"nombre"},{"enonce":"Que conclure du sondage ?","aide":"Compare 0,47 aux bornes de l’intervalle de fluctuation.","type":"choix","options":[{"id":"a","texte":"La fréquence 0,47 est dans l’intervalle : le directeur a donc démontré que la moitié des élèves est favorable"},{"id":"b","texte":"Le sondage est inutilisable, car 400 élèves représentent moins que les 1 500 du lycée"},{"id":"c","texte":"La fréquence 0,47 est inférieure à 0,5 : le directeur a nécessairement tort"},{"id":"d","texte":"La fréquence 0,47 est dans l’intervalle [0,45 ; 0,55] : le sondage est compatible avec l’affirmation"}],"multiple":false},{"enonce":"Quelle taille d’échantillon donne 1/√n = 0,025 ?","aide":"Si 1/√n = 0,025, alors √n = 1 ÷ 0,025 = 40.","type":"nombre"},{"enonce":"Par combien faut-il multiplier n pour diviser par 3 la largeur de l’intervalle de fluctuation ?","aide":"Regarde le tableau : de n = 100 à n = 900, 1/√n passe de 0,1 à 0,033.","type":"choix","options":[{"id":"a","texte":"Par 9"},{"id":"b","texte":"Par 3"},{"id":"c","texte":"Par 6"},{"id":"d","texte":"Par 27"}],"multiple":false}]}$ex$::jsonb,
