  ('fc033f4e-c8a3-5acb-9285-1dda750800d4'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une carte postale de Grenade","competence":"analyser-document","situation":"Sofía est en voyage à Grenade. Elle écrit à son amie Elena, et le professeur en tire un tableau de pluriels.","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Carta de Sofía","blocs":["Querida Elena:","Granada es preciosa. El clima es seco y no hay ningún problema con el idioma: todos hablan despacio.","Ayer visité el museo y vi un cuadro con mucha sangre. Luego comí pan con miel.","Un abrazo, Sofía"],"source":"Texte écrit pour l’exercice"},{"id":"plurales","type":"tableau","titre":"Pluriels à compléter","colonnes":["Singular","Plural"],"lignes":[["la crisis","?"],["el rubí","?"],["el jueves","?"],["la luz","?"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois noms masculins** terminés en -a dans la lettre.","aide":"Ce sont des mots d’origine grecque : el … ma.","type":"zone","document":"carta","multiple":true},{"enonce":"Quelle phrase de Sofía est correcte ?","aide":"Color est masculin, sangre est féminin.","type":"choix","options":[{"id":"a","texte":"El color de la sangre es rojo."},{"id":"b","texte":"La color del sangre es rojo."},{"id":"c","texte":"El color de el sangre es rojo."},{"id":"d","texte":"La color de la sangre es rojo."}],"multiple":false},{"enonce":"Complète les pluriels du tableau.","aide":"Voyelle accentuée : -es. Mot en -s non accentué sur la dernière syllabe : invariable. -z : -ces.","type":"trous","segments":["la crisis → las ",0," ; el rubí → los ",1," ; el jueves → los ",2," ; la luz → las ",3],"banque":["crisis","luces","jueves","crises","rubís","luzes","rubíes"]},{"enonce":"Range chaque nom selon la formation de son pluriel.","aide":"Regarde la dernière lettre du mot.","type":"categories","categories":[{"id":"c0","texte":"+ s"},{"id":"c1","texte":"+ es"},{"id":"c2","texte":"z → ces"},{"id":"c3","texte":"Invariable"}],"items":[{"id":"i0","texte":"lunes"},{"id":"i1","texte":"libro"},{"id":"i2","texte":"ciudad"},{"id":"i3","texte":"crisis"},{"id":"i4","texte":"casa"},{"id":"i5","texte":"vez"},{"id":"i6","texte":"papel"},{"id":"i7","texte":"lápiz"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m13","m16"]},"explication":"**clima, problema, idioma** : les noms en -ma d’origine grecque sont masculins."},{"cle":{"type":"choix","ids":["a"]},"explication":"**El color de la sangre** : *el color* (masculin) et *la sangre* (féminin) ; *de el* ne s’écrit jamais."},{"cle":{"type":"trous","trous":[["crisis"],["rubies"],["jueves"],["luces"]]},"affichage":"crisis · rubíes · jueves · luces","explication":"**crisis** et **jueves** sont invariables ; **rubíes** (voyelle accentuée + -es) ; **luces** (-z → -ces)."},{"cle":{"type":"categories","items":{"i0":"c3","i1":"c0","i2":"c1","i3":"c3","i4":"c0","i5":"c2","i6":"c1","i7":"c2"}},"explication":"Voyelle → **-s** ; consonne → **-es** ; **-z → -ces** ; -s non accentué sur la dernière syllabe → **invariable**."}]$ex$::jsonb),
  ('69fd91a0-ffbb-569f-b487-d0d5523e6d23'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le courriel de Marta à son correspondant","competence":"comprendre-langue","situation":"Marta écrit à Pablo, son correspondant français. Elle lui parle de sa journée, de la veille et de son enfance.","documents":[{"id":"correo","type":"texte","genre":"lettre","titre":"Correo de Marta","blocs":["Hola, Pablo:","Hoy he escrito mi primer correo en francés. Ayer comí en casa de mi abuela y por la tarde vimos una película.","Cuando era pequeña, mi abuela cocinaba paella todos los domingos."],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui forment le *pretérito perfecto* dans le courriel.","aide":"Il se compose de haber au présent et d’un participe passé ; le marqueur « Hoy » l’appelle.","type":"zone","document":"correo","multiple":true},{"enonce":"Touche les **deux verbes à l’indefinido** : des actions achevées, coupées du présent.","aide":"Cherche les actions de la veille, introduites par le marqueur « Ayer ».","type":"zone","document":"correo","multiple":true},{"enonce":"Marta dit ce que faisait sa grand-mère chaque dimanche. Complète.","aide":"Une habitude du passé appelle l’imperfecto ; regarde aussi la personne du verbe.","type":"trous","segments":["Todos los domingos mi abuela ",0," paella."],"banque":["cocinó","ha cocinado","cocinaban","cocinaba"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m4"]},"explication":"**he escrito** : *haber* au présent + participe passé. Le perfecto relie l’action à aujourd’hui (« Hoy… »)."},{"cle":{"type":"zone","ids":["m11","m21"]},"explication":"**comí** et **vimos** sont à l’indefinido : *ayer* coupe l’action du présent, l’action est achevée."},{"cle":{"type":"trous","trous":[["cocinaba"]]},"affichage":"cocinaba","explication":"**cocinaba** : une habitude (« todos los domingos ») se met à l’imperfecto, ici à la 3e personne du singulier (-aba)."}]$ex$::jsonb),
  ('69fd91a0-ffbb-569f-b487-d0d5523e6d23'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Messages après une soirée sous la pluie","competence":"manier-langue","situation":"Lucas et Irene s’écrivent le lendemain d’une journée pluvieuse. À toi de choisir le bon passé dans chaque phrase.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Messages d’Irene et de Lucas","participants":[{"nom":"Irene","emoji":"👧","cote":"gauche"},{"nom":"Lucas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Irene","texte":"Lucas, ¿qué hiciste ayer?"},{"qui":"Lucas","texte":"Ayer fui a casa de Sara. Llovía mucho cuando salí de casa."},{"qui":"Irene","texte":"Yo me quedé en casa. Hoy he llegado tarde a clase."},{"qui":"Lucas","texte":"Mi abuelo siempre decía que la lluvia trae suerte."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes à l’imperfecto** : l’un plante un décor, l’autre dit une habitude.","aide":"Un verbe suit « siempre », l’autre dit ce qui durait quand Lucas est sorti.","type":"zone","document":"chat","multiple":true},{"enonce":"Touche le **marqueur de temps** qui appelle le *pretérito perfecto* (« he llegado »).","aide":"C’est un mot qui dit que le moment n’est pas encore fini.","type":"zone","document":"chat","multiple":false},{"enonce":"Associe chaque marqueur au temps qu’il appelle.","aide":"Pense à l’action achevée, au passé relié à aujourd’hui et à l’habitude.","type":"association","gauche":[{"id":"g0","texte":"ayer"},{"id":"g1","texte":"hoy"},{"id":"g2","texte":"siempre"}],"droite":[{"id":"d0","texte":"indefinido"},{"id":"d1","texte":"imperfecto"},{"id":"d2","texte":"perfecto"}]},{"enonce":"Complète avec la forme qui convient (nosotros, une action achevée la veille).","aide":"Ayer coupe du présent ; la personne est nosotros.","type":"trous","segments":["Ayer nosotros ",0," paella en casa de Sara."],"banque":["comemos","comieron","hemos comido","comimos"]},{"enonce":"Remets en ordre : « Il dormait quand le téléphone a sonné. » La phrase commence par Dormía.","aide":"L’imperfecto plante le décor, l’indefinido l’interrompt.","type":"ordre","items":[{"id":"a","texte":"cuando"},{"id":"b","texte":"sonó"},{"id":"c","texte":"Dormía"},{"id":"d","texte":"el teléfono"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m30"]},"explication":"**Llovía** (le décor) et **decía** (l’habitude : « siempre ») sont à l’imperfecto ; *fui*, *salí* et *me quedé* sont des actions achevées."},{"cle":{"type":"zone","ids":["m21"]},"explication":"**Hoy** : la journée n’est pas finie, le passé reste relié au présent, donc *he llegado*."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"*Ayer* → **indefinido** (achevé), *hoy* → **perfecto** (relié au présent), *siempre* → **imperfecto** (habitude)."},{"cle":{"type":"trous","trous":[["comimos"]]},"affichage":"comimos","explication":"**comimos** : indefinido de *comer* à nosotros (-imos). *Hemos comido* serait fautif avec *ayer*."},{"cle":{"type":"ordre","ids":["c","a","b","d"]},"explication":"**Dormía cuando sonó el teléfono** : le décor à l’imperfecto, l’événement qui survient à l’indefinido."}]$ex$::jsonb),
  ('69fd91a0-ffbb-569f-b487-d0d5523e6d23'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une nuit d’été à Séville","competence":"analyser-texte","situation":"Un récit de voyage mêle décor et événements. Une fiche de correction relève quatre phrases, dont une est fausse.","documents":[{"id":"noche","type":"texte","genre":"recit","titre":"Una noche en Sevilla","blocs":["Era una noche de verano en Sevilla. Hacía calor y la gente paseaba por la plaza.","De pronto, un músico empezó a cantar y todos se callaron. Cuando terminó, los turistas aplaudieron."],"source":"Texte écrit pour l’exercice"},{"id":"fichas","type":"tableau","titre":"Cuatro frases del cuaderno","colonnes":["Frase del alumno"],"lignes":[["Hoy he estudiado mucho."],["El año pasado viajé a Cuba."],["Ayer he comido paella."],["Esta semana he trabajado mucho."]],"enteteLignes":false,"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes qui plantent le décor** (imperfecto).","aide":"Ils disent ce qui durait : la nuit, la chaleur, les promenades.","type":"zone","document":"noche","multiple":true},{"enonce":"Touche les **quatre verbes qui font avancer l’action** (indefinido).","aide":"Ce sont des événements qui surviennent, chacun achevé.","type":"zone","document":"noche","multiple":true},{"enonce":"Dans le tableau, une phrase est **fautive**. Touche-la.","aide":"Regarde le marqueur de temps : est-il coupé du présent ou relié à lui ?","type":"zone","document":"fichas","multiple":false},{"enonce":"Pourquoi « Ayer he comido paella » est-elle fautive ?","aide":"Compare avec « Hoy he estudiado mucho » : qu’est-ce qui change ?","type":"choix","options":[{"id":"a","texte":"Avec ayer, l’espagnol exige toujours l’imparfait pour manger"},{"id":"b","texte":"Le mot paella impose le pretérito imperfecto dans ce cas"},{"id":"c","texte":"Le perfecto est réservé aux verbes en -ar, pas en -er"},{"id":"d","texte":"Ayer situe l’action hors du présent : il faut l’indefinido"}],"multiple":false},{"enonce":"Associe chaque verbe (personne et temps indiqués) à sa forme.","aide":"L’imparfait n’a que trois irréguliers : ser, ir, ver.","type":"association","gauche":[{"id":"g0","texte":"comer (él, indefinido)"},{"id":"g1","texte":"hablar (ellos, indefinido)"},{"id":"g2","texte":"vivir (nosotros, imparfait)"},{"id":"g3","texte":"ir (yo, imparfait)"}],"droite":[{"id":"d0","texte":"hablaron"},{"id":"d1","texte":"iba"},{"id":"d2","texte":"vivíamos"},{"id":"d3","texte":"comió"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m7","m12"]},"explication":"**Era, Hacía, paseaba** : l’imperfecto décrit le décor et ce qui durait."},{"cle":{"type":"zone","ids":["m20","m26","m28","m31"]},"explication":"**empezó, callaron, terminó, aplaudieron** : chaque événement rompt le décor, l’action avance."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"**Ayer he comido paella** est fautive : *ayer* coupe du présent, il faut *Ayer comí paella*."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Ayer coupe l’action du présent** : on emploie l’indefinido (*comí*). Le perfecto est réservé à ce qui touche encore à aujourd’hui."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"*comió* (-ió), *hablaron* (-aron), *vivíamos* (-íamos), *iba* (ir est un des trois irréguliers de l’imparfait)."}]$ex$::jsonb),
  ('aee977f3-15a3-504d-97a9-5573545e550f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Qui nettoie le tableau ?","competence":"comprendre-langue","situation":"Dans la classe d’Álex, la professeure fait des annonces par message. Les virgules changent tout.","documents":[{"id":"clase","type":"dialogue","modele":"sms","titre":"Groupe de classe","participants":[{"nom":"Profesora","emoji":"👩‍🏫","cote":"gauche"},{"nom":"Álex","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Profesora","texte":"Los alumnos que llegan tarde limpian la pizarra."},{"qui":"Álex","texte":"Yo llego tarde a veces. ¿Y mis compañeros?"},{"qui":"Profesora","texte":"Tus compañeros, que llegan temprano, ganan un punto."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Qui doit nettoyer le tableau ?","aide":"La première relative n’a pas de virgules.","type":"choix","options":[{"id":"a","texte":"Seulement les élèves qui arrivent en retard"},{"id":"b","texte":"Tous les élèves de la classe"},{"id":"c","texte":"Personne"},{"id":"d","texte":"Seulement les élèves qui arrivent à l’heure"}],"multiple":false},{"enonce":"Touche le « que » de la relative **explicative** (celle qui est entre virgules).","aide":"C’est dans le dernier message de la professeure.","type":"zone","document":"clase","multiple":false},{"enonce":"Remets en ordre : « La maison dans laquelle je vis. » La phrase commence par La.","aide":"La préposition précède toujours le relatif.","type":"ordre","items":[{"id":"a","texte":"casa"},{"id":"b","texte":"en la que"},{"id":"c","texte":"vivo"},{"id":"d","texte":"La"}]}]}$ex$::jsonb,
