   $ex${"titre":"Une secrétaire pour l’entreprise","competence":"analyser-document","situation":"L’entreprise Solmar recrute. Une annonce décrit la personne cherchée, et deux collègues discutent d’une secrétaire déjà connue.","documents":[{"id":"anuncio","type":"texte","genre":"article","titre":"Se busca secretaria","blocs":["La empresa Solmar busca una secretaria que hable inglés y que tenga coche.","De momento no hay ningún candidato que sepa ruso."],"source":"Annonce écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages au bureau","participants":[{"nom":"Jefe","emoji":"👨","cote":"gauche"},{"nom":"Marta","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Jefe","texte":"¿Conoces a la secretaria que habla inglés?"},{"qui":"Marta","texte":"Sí, la conozco. Se llama Ana."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes au subjonctif** de l’annonce.","aide":"Ils décrivent une personne qu’on ne connaît pas encore.","type":"zone","document":"anuncio","multiple":true},{"enonce":"Dans le message du chef, pourquoi *habla* est-il à l’indicatif ?","aide":"Le chef connaît-il la secrétaire dont il parle ?","type":"choix","options":[{"id":"a","texte":"Parce que inglés est un nom masculin"},{"id":"b","texte":"Parce que la phrase est écrite au présent"},{"id":"c","texte":"Parce que Marta répond « oui » ensuite"},{"id":"d","texte":"Il parle d’une secrétaire précise, déjà connue"}],"multiple":false},{"enonce":"Complète avec le bon verbe.","aide":"La première secrétaire est connue ; la seconde personne est niée.","type":"trous","segments":["Mi jefe busca a la secretaria que ",0," por teléfono: es Ana. No conozco a nadie que ",1," la respuesta."],"banque":["hable","habla","sabe","sepa"]},{"enonce":"Range chaque phrase selon le mode de la relative.","aide":"Le chico existe-t-il déjà, ou reste-t-il à trouver ?","type":"categories","categories":[{"id":"c0","texte":"Antécédent connu : indicatif"},{"id":"c1","texte":"Antécédent indéfini ou nié : subjonctif"}],"items":[{"id":"i0","texte":"Conozco a un chico que habla chino"},{"id":"i1","texte":"No hay nadie que hable chino"},{"id":"i2","texte":"Busco un chico que hable chino"},{"id":"i3","texte":"Tengo un amigo que habla chino"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m11","m20"]},"explication":"**hable, tenga, sepa** : l’antécédent est indéfini ou nié, donc la relative est au subjonctif."},{"cle":{"type":"choix","ids":["d"]},"explication":"**habla** : l’antécédent est connu, réel (Ana), donc on emploie l’indicatif."},{"cle":{"type":"trous","trous":[["habla"],["sepa"]]},"affichage":"habla · sepa","explication":"**que habla** (antécédent connu : indicatif) et **que sepa** (antécédent nié : subjonctif)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"L’indicatif quand on connaît la personne ; le subjonctif quand on la cherche ou qu’on nie qu’elle existe."}]$ex$::jsonb),
  ('aee977f3-15a3-504d-97a9-5573545e550f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La lettre de Diego","competence":"manier-langue","situation":"Diego écrit à sa cousine Julia depuis sa nouvelle maison. Dans sa lettre, il emploie plusieurs relatives.","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Carta de Diego","blocs":["Querida Julia:","Mi vecino toca la trompeta de noche, lo que no nos deja dormir.","Mi hermana Rosa, quien vive en Lima, llega mañana. Los primos que viven en Cádiz llegan el domingo.","Un abrazo, Diego"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui reprennent **toute l’idée** de la première partie de la phrase du voisin.","aide":"C’est un pronom neutre en deux mots.","type":"zone","document":"carta","multiple":true},{"enonce":"Dans la lettre, que fait la relative « quien vive en Lima » ?","aide":"Elle est entourée de virgules.","type":"choix","options":[{"id":"a","texte":"Elle distingue Rosa des autres sœurs de Diego"},{"id":"b","texte":"Elle remplace le sujet de la phrase principale"},{"id":"c","texte":"Elle exprime un doute à propos de Rosa et du voyage"},{"id":"d","texte":"Elle ajoute une information sur Rosa sans la distinguer"}],"multiple":false},{"enonce":"Remets en ordre : « Le garçon dont je parle. » La phrase commence par El.","aide":"La préposition de se place avant le relatif.","type":"ordre","items":[{"id":"a","texte":"chico"},{"id":"b","texte":"del que"},{"id":"c","texte":"hablo"},{"id":"d","texte":"El"}]},{"enonce":"Complète avec le bon relatif.","aide":"Cuyo s’accorde avec ce qui est possédé : novela.","type":"trous","segments":["El libro del ",0," te hablé es este. El escritor ",1," novela leí es famoso. Llegó tarde, ",2," me molestó."],"banque":["que","quien","cuyo","cuya","lo que"]},{"enonce":"Range chaque phrase : la relative est-elle déterminative (elle restreint) ou explicative (elle ajoute) ?","aide":"Regarde les virgules.","type":"categories","categories":[{"id":"c0","texte":"Déterminative (elle restreint)"},{"id":"c1","texte":"Explicative (elle ajoute)"}],"items":[{"id":"i0","texte":"Mi tía, que vive en Lima, llega mañana"},{"id":"i1","texte":"Los vecinos, que son simpáticos, nos ayudan"},{"id":"i2","texte":"Las chicas que juegan al fútbol entrenan hoy"},{"id":"i3","texte":"Los perros que ladran mucho molestan"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m10"]},"explication":"**lo que** reprend une idée entière (il joue de la trompette de nuit) ; on n’emploie jamais *el que* pour une phrase."},{"cle":{"type":"choix","ids":["d"]},"explication":"Entre virgules, la relative est **explicative** : elle ajoute une information. *Quien* est possible pour une personne."},{"cle":{"type":"ordre","ids":["d","a","b","c"]},"explication":"**El chico del que hablo** : *de* + *el que* se contractent en *del que*, devant le verbe."},{"cle":{"type":"trous","trous":[["que"],["cuya"],["lo que"]]},"affichage":"que · cuya · lo que","explication":"**del que**, **cuya novela** (accord avec novela, féminin) et **lo que** (il reprend la phrase entière)."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Avec virgules : explicative (elle s’applique à tous). Sans virgules : déterminative (elle restreint)."}]$ex$::jsonb)
) AS v (chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu, cles);

INSERT INTO public.exercices (id, chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu)
SELECT s.id, s.chapter_id, s.position, s.etoiles, s.gemmes, s.xp, s.nb_questions, s.contenu
FROM exercices_seed s
JOIN public.chapters c ON c.id = s.chapter_id
ON CONFLICT (id) DO UPDATE
  SET etoiles      = EXCLUDED.etoiles,
      nb_questions = EXCLUDED.nb_questions,
      contenu      = EXCLUDED.contenu,
      updated_at   = now();

INSERT INTO public.exercices_cles (exercice_id, cles)
SELECT s.id, s.cles
FROM exercices_seed s
JOIN public.exercices e ON e.id = s.id
ON CONFLICT (exercice_id) DO UPDATE SET cles = EXCLUDED.cles;

-- Contrôle : combien d'exercices de ce fichier sont en base, et combien sautés.
DO $$
DECLARE
  v_attendus INTEGER;
  v_poses    INTEGER;
BEGIN
  SELECT count(*) INTO v_attendus FROM exercices_seed;
  SELECT count(*) INTO v_poses FROM public.exercices e JOIN exercices_seed s ON s.id = e.id;
  RAISE NOTICE 'Cahier 1re (9) : % exercices posés sur % (les autres n''ont pas leur chapitre en base).', v_poses, v_attendus;
  DROP TABLE IF EXISTS pg_temp.exercices_seed;
END $$;
